-- Opaque public reference numbers (data only — no schema change).
-- Listings move from sequential EQ-#### to random ZX- stock numbers so
-- customers cannot infer how many listings or requests exist. Database ids
-- are unchanged. Each UPDATE is guarded by the old value, so this is a
-- no-op on databases that never had these rows. New references are
-- generated by src/lib/reference.ts (random + Luhn mod-32 check).

UPDATE "Equipment" SET "reference" = 'ZX-9BVK1Q' WHERE "id" = 1 AND "reference" = 'EQ-0001';
UPDATE "Equipment" SET "reference" = 'ZX-BZFMT4' WHERE "id" = 2 AND "reference" = 'EQ-0002';
