-- Requests that pointed at a listing by its old reference follow it.
UPDATE "Lead" SET "relatedRef" = (SELECT e."reference" FROM "Equipment" e WHERE e."id" = CAST(substr("Lead"."relatedRef", 4) AS INTEGER))
WHERE "relatedRef" GLOB 'EQ-[0-9]*'
  AND EXISTS (SELECT 1 FROM "Equipment" e WHERE e."id" = CAST(substr("Lead"."relatedRef", 4) AS INTEGER) AND e."reference" GLOB 'ZX-*');
